package glitch

import data.glitch_lib

# Integrity-related field names that should be present
integrity_fields := {"checksum", "integrity", "verify", "validation", "hmac", "mac", "hash", "signature", "checksum_algorithm", "hash_verification", "digital_signature", "message_integrity", "expected_checksum", "expected_hash", "checksum_value", "signature_url", "gpg_key", "signing_key", "integrity_file", "manifest_checksum", "digest", "cosign", "notation", "auth_tag", "icv", "message_authentication", "request_checksum", "response_validation", "commit_signature_verification", "gpg_verify_commits", "trusted_gpg_key", "gpgcheck", "tls_verify", "verify_ssl", "request_signature", "integrity_check"}

# Dangerous disable/skip patterns
dangerous_disable_patterns := {"disable_checksum", "skip_validation", "no_verify", "verify_checksum", "skip_checksum_validation", "ignore_signature", "insecure_skip_verify", "verify_hash", "verify_signature"}

# Insecure values that indicate disabled integrity
insecure_values := {"false", "disabled", "off", "none", "null", "~", "no", "skip", "bypass"}

# Protocols that typically need integrity checks
protocols_needing_integrity := {"udp", "tcp", "http", "ftp", "tftp"}

# Resource types that typically handle artifacts/downloads
artifact_resource_types := {"download", "get_url", "curl", "wget", "fetch", "package", "archive", "file", "image", "container", "docker_image", "git", "repository", "source"}

# Check if a value represents an insecure/disabled setting
is_insecure_value(value) {
    value.ir_type == "String"
    lower(value.value) == insecure_values[_]
} else {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "Null"
    true
} else {
    value.ir_type == "Undef"
    true
}

# Check if attribute name matches dangerous disable pattern
is_dangerous_disable(name) {
    lower_name := lower(name)
    contains(lower_name, dangerous_disable_patterns[_])
} else {
    lower_name := lower(name)
    regex.match(".*(insecure|skip|bypass|disable|force).*(verify|check|validate|integrity|checksum|hash|signature).*", lower_name)
}

# Check if attribute name indicates integrity field
is_integrity_field(name) {
    lower_name := lower(name)
    contains(lower_name, integrity_fields[_])
}

# Extract all nested values from complex structures (Hash, Array)
extract_values(value) = values {
    value.ir_type == "Hash"
    values = {v | some k; v := value.value[k]}
} else = values {
    value.ir_type == "Array"
    values = {v | v := value.value[_]}
} else = values {
    values = {value}
}

# Check if any value in nested structure is insecure
has_insecure_value(value) {
    vals := extract_values(value)
    val := vals[_]
    is_insecure_value(val)
}

# Find all keys in a Hash structure recursively
collect_keys(value) = keys {
    value.ir_type == "Hash"
    base_keys := {k | some k, _; value.value[k]}
    nested_keys := {nk | some k, v; v := value.value[k]; v.ir_type in {"Hash", "Array"}; nk := collect_keys(v)[_]}
    keys := base_keys | nested_keys
} else = keys {
    value.ir_type == "Array"
    nested_keys := {nk | a := value.value[_]; a.ir_type in {"Hash", "Array"}; nk := collect_keys(a)[_]}
    keys := nested_keys
} else = keys {
    keys := set()
}

# Get string value safely
get_string(value) = s {
    value.ir_type == "String"
    s := lower(value.value)
} else = s {
    s := ""
}

# Pattern 1: Explicitly disabled integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check if this is a resource type that might handle integrity
    unit_type_lower := lower(node.type)
    contains(unit_type_lower, artifact_resource_types[_])

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for dangerous disable flags set to insecure values
    is_dangerous_disable(attr.name)
    has_insecure_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Integrity verification explicitly disabled or set to insecure value. (CWE-353)"
    }
}

# Pattern 2: verify_ssl/tls_verify/insecure_skip_verify set to disable verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_name_lower := lower(attr.name)
    attr_name_lower in {"tls_verify", "insecure_skip_verify", "verify_ssl", "ssl_verify", "validate_certs"}

    # Check if set to false or insecure value
    has_insecure_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - TLS/SSL verification disabled, compromising integrity of communications. (CWE-353)"
    }
}

# Pattern 3: File downloads without integrity verification fields
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    # Check if this looks like a download/get_url/file resource
    unit_type_lower := lower(node.type)
    contains(unit_type_lower, {"download", "get_url", "curl", "wget", "fetch", "remote_file"})

    attrs := glitch_lib.all_attributes(node)
    attr_list := [a.name | a := attrs[_]]
    attr_set := {lower(name) | name := attr_list[_]}

    # Has source/URL but missing integrity fields
    has_url := {r | r := attr_set["url"]; true} | {r | r := attr_set["source"]; true} | {r | r := attr_set["src"]; true}
    count(has_url) > 0

    # Check for absence of integrity verification
    not has_integrity_verification(attr_set)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - File download without checksum, hash, or signature verification. (CWE-353)"
    }
}

# Pattern 4: Package installations without integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    unit_type_lower := lower(node.type)
    contains(unit_type_lower, {"package", "yum", "apt", "dnf", "rpm", "dpkg", "pkg", "gem", "npm", "pip", "composer"})

    attrs := glitch_lib.all_attributes(node)
    attr_list := [a.name | a := attrs[_]]
    attr_set := {lower(name) | name := attr_list[_]}

    # Check for disabled GPG/signature verification
    gpg_disabled := attr_set["gpgcheck"] == "0"
    gpg_disabled == true

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Package installation with GPG/signature verification disabled. (CWE-353)"
    }
}

# Pattern 5: Container image pulls without digest or signature verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    unit_type_lower := lower(node.type)
    contains(unit_type_lower, {"docker", "container", "podman", "image", "kubernetes"})

    attrs := glitch_lib.all_attributes(node)
    attr_list := [a.name | a := attrs[_]]
    attr_set := {lower(name) | name := attr_list[_]}
    attr_values := { {lower(a.name): get_string(a.value)} | a := attrs[_] }

    # Has image reference but no digest verification
    has_image := {r | r := attr_set["image"]; true} | {r | r := attr_set["container_image"]; true}
    count(has_image) > 0

    # Check if using tag instead of digest
    some akey, aval
    aval := attr_values[akey]
    akey in {"image", "container_image"}
    regex.match(".*:[^@]+$", aval)  # Has tag but not digest

    # No digest field present
    not attr_set["digest"]
    not attr_set["image_digest"]

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Container image using mutable tag without digest verification. (CWE-353)"
    }
}

# Pattern 6: Git sources without signature verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr_list := [a.name | a := attrs[_]]
    attr_set := {lower(name) | name := attr_list[_]}

    # Git-related configuration
    has_git := {r | r := attr_set["git"]; true} | {r | r := attr_set["repository"]; true} | {r | r := attr_set["repo"]; true} | {r | r := attr_set["source"]; true}
    count(has_git) > 0

    # Check for insecure git configuration
    some attr
    attr := attrs[_]
    lower(attr.name) == "force"
    is_insecure_value(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing support for integrity check - Git repository access with force flag overriding verification. (CWE-353)"
    }
}

# Helper: Check if integrity verification is present
has_integrity_verification(attr_set) {
