} else {
    attr_set["checksums"]
} else {
    attr_set["md5"]
} else {
    attr_set["sha256"]
} else {
    attr_set["sha512"]
} else {
    attr_set["hash"]
} else {
    attr_set["signature"]
} else {
    attr_set["gpg_key"]
} else {
    attr_set["verify_checksum"]
} else {
    attr_set["checksum_validation"]
}

