package glitch

import data.glitch_lib

insecure_values := {"false", "disabled", "off", "none", "null", "~", "no", "skip", "bypass", "0", "false\n", "no\n"}

verify_patterns := {"verify", "validate", "verification", "val", "insecure", "skip", "bypass", "disable", "trust", "gpg", "gpgcheck", "signature", "checksum", "hash", "ssl", "tls", "cert", "peer", "skip_verify", "no_verify", "check"}

download_indicators := {"url", "source", "src", "uri", "download", "wget", "curl", "fetch", "get", "pull", "remote", "http", "https", "ftp", "archive", "package", "gem", "npm", "pip", "maven"}

is_insecure_value(value) {
    value.ir_type == "String"
    lower(trim_right(value.value, "\n")) == insecure_values[_]
} else {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "Integer"
    value.value == 0
} else {
    value.ir_type == "Null"
}

contains_verify_pattern(name) {
    lower(name) == verify_patterns[_]
} else {
    n := lower(name)
    some p in verify_patterns
    contains(n, p)
}

contains_download_indicator(name) {
    lower(name) == download_indicators[_]
} else {
    n := lower(name)
    some d in download_indicators
    contains(n, d)
}

# Helper to get atomic unit attributes as a set
get_au_attrs(au) = attrs {
    attrs := {a | 
        walk(au, [_, n])
        n.ir_type == "Attribute"
        a := n
    }
}

# Check if attribute is a URL/source with external scheme
is_external_url(attr) {
    attr.value.ir_type == "String"
    startswith(lower(attr.value.value), "http")
} else {
    attr.value.ir_type == "String"
    startswith(lower(attr.value.value), "ftp")
}

has_external_url(attrs) {
    attr := attrs[_]
    contains_download_indicator(attr.name)
    is_external_url(attr)
}

has_verify_attr(attrs) {
    attr := attrs[_]
    contains_verify_pattern(attr.name)
}

verify_disabled(attrs) {
    attr := attrs[_]
    contains_verify_pattern(attr.name)
    is_insecure_value(attr.value)
}

has_integrity_attr(attrs) {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "checksum") 
} else {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "hash")
} else {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "signature")
} else {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "digest")
} else {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "sha") 
} else {
    attr := attrs[_]
    n := lower(attr.name)
    contains(n, "md5")
}

# Rule 1: Explicitly disabled verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, node])
    node.ir_type == "Attribute"
    node.name
    node.value

    contains_verify_pattern(node.name)
    is_insecure_value(node.value)

    result := {
        "type": "sec_no_int_check",
        "element": node,
        "path": parent.path,
        "description": "Missing support for integrity check - Verification/validation explicitly disabled. (CWE-353)"
    }
}

# Rule 2: External download without integrity verification
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, au])
    au.ir_type == "AtomicUnit"

    attrs := get_au_attrs(au)
    count(attrs) > 0

    # Has external URL/source
    has_external_url(attrs)

    # No verify attr, integrity attr, or validation mechanism
    not has_integrity_attr(attrs)
    not has_verify_attr(attrs)

    result := {
        "type": "sec_no_int_check",
        "element": au,
        "path": parent.path,
        "description": "Missing support for integrity check - External download without integrity verification mechanism. (CWE-353)"
    }
}

# Rule 3: Package/file download with verification disabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, au])
    au.ir_type == "AtomicUnit"

    t := lower(au.type)
